(* [comment removed for export] *)
Lemma leaf_view : forall i c k ps1 t pv lv pe ce d E1 E' R' (M1 M' : mem) bm bd stack buf,
  is_leaf i c k ps1 t -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  PSIU.contents I pv pe ce E1 M1 bm bd stack buf ->
  know_ok RSEGS E' M' (PSM2.lcells ps1) /\
  uv E' (PB4.pv_level lv) = uv E1 (PB4.pv_level pv) /\ uv E' (PB4.pv_sb lv) = uv E1 (PB4.pv_sb pv) /\ uv E' (PB4.pv_send lv) = uv E1 (PB4.pv_send pv) /\ uv E' (PB4.pv_scend lv) = uv E1 (PB4.pv_scend pv) /\
  uv E' (PB4.pv_wend lv) = wend /\ uv E' pe = uv E1 pe /\ uv E' ce = uv E1 ce /\
  (uv E' (PB4.pv_st pv) = uv E1 (PB4.pv_st pv) /\ uv E' (PB4.pv_more pv) = uv E1 (PB4.pv_more pv) /\ uv E' (PB4.pv_level pv) = uv E1 (PB4.pv_level pv)) /\
  uv E' (PB4.pv_st lv) = match PSM2.d_st d with None => uv E1 (PB4.pv_st pv) | Some e => uv E' e end /\
  uv E' (PB4.pv_sst lv) = PSBU.newv (PSM2.d_sst d) (uv E1 (PB4.pv_sst pv)) /\ uv E' (PB4.pv_nst lv) = PSBU.newv (PSM2.d_nst d) (uv E1 (PB4.pv_nst pv)) /\
  uv E' (PB4.pv_more lv) = PSBU.newv (PSM2.d_more d) (uv E1 (PB4.pv_more pv)) /\ uv E' (PB4.pv_done lv) = PSBU.newv (PSM2.d_done d) (uv E1 (PB4.pv_done pv)) /\
  uv E' (PB4.pv_size lv) = (if PSM2.d_clr d then 0 else uv E1 (PB4.pv_size pv)) /\
  uv E' (PB4.pv_wptr lv) = uv E1 (PB4.pv_wptr pv) + PSM2.d_adv d /\ 0 <= PSM2.d_adv d <= 1 /\ uv E' (PB4.pv_wptr lv) <= wend /\
