Lemma vis_leaf_okE : forall (pc : Z) (ev : PMES.eev) (Args : list (Z * Z) -> bvmap 5 word -> mem -> Prop) (Extra : env -> Prop) (KXE BXE : env -> Z) i c k ps0 j cj ci,
  PMES.vtransU L HI PMES.WD_SCR_X pc ev Args ->
  is_leaf i c k ps0 (CC.TOther pc) -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj -> SR.ps_pc ps0 = pc ->
  VBX.vis_chk GT.NF G.HDECL Vb c ps0 cj (nth i G.BLS []) (nth j G.BLS []) = Some ci ->
  (forall E1 R1 (M1 : mem) model1 E' R' (M' : mem) cr, CC.At (hl_segs L) c E1 R1 M1 ->
     CH2V.heap_ambV L HI GT.NF E0 model LBo sp G.HDECL W G.BLS PMES.eghost VBX.gB (PSIU.Cred I) eg M0c i E1 M1 model1 -> XIv i E1 M1 ->
     env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps0 E' R' M1 M' ->
     CH2.common_facts_x L HI GT.NF E0 M0c model (CH2V.LBr LBo PMES.eghost VBX.gB eg) sp G.HDECL W G.BLS Cred VBX.VIS_SCR 0 c ps0 cj ci i E1 E' R' M' model1 ->
     hi_heap HI ((CH2.den E' (nth i G.BLS []) ++ LBo) ++ PMES.g_lbv eg) cr M' (m_vmmaps model1) -> Cred i E1 cr ->
     Args (CH2.den E' (nth i G.BLS []) ++ LBo) R' M' /\ PMES.enc_inv M' V S2 eg /\ PMES.ev_guard (PMES.g_es eg) ev /\ PMES.eroomU eg ev /\
     PML.img_ro M' /\ PML.lits_ok M' /\ PMES.ecreditU L cr eg (KXE E1) (BXE E1) /\ Extra E1) ->
  (forall E1 E' R' (M1 M' : mem) E2 (M2 : mem) g' cr', XIv i E1 M1 -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' ->
     CC.leaf_facts (hl_segs L) c ps0 E' R' M1 M' -> env_agree (CH2.ci_nx ci) E' E2 -> (CC.cp_nx c <= CH2.ci_nx ci)%nat ->
     L5C.hpres L (CH2.den E' (nth i G.BLS []) ++ LBo) (sp + CH2.ci_csp ci) VBX.VIS_SCR (PMES.W_enc V S2) M' M2 ->
     PMES.enc_inv M2 V S2 g' -> PML.lits_ok M2 -> PMES.g_es g' = PMES.estep (PMES.g_es eg) ev ->
     (exists pay, PMES.pay_ok ev pay /\ PMES.g_len g' = PMES.g_len eg + PMES.ev_ind (PMES.g_es eg) ev + pay) -> Extra E1 ->
     PMES.ecreditU L cr' g' (KXE E1) (BXE E1) -> PSIU.XIv I g' j E2 M2 /\ PSIU.Cred I g' j E2 cr') ->
  CH2V.leaf_okV L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS PMES.eghost VBX.gB (PSIU.Cred I) (PSIU.XIv I) G.CPS K PML.fp_ok eg M0c i c ps0.
Proof.
  intros pc ev Args Extra KXE BXE i c k ps0 j cj ci VS IL Hret Hcj Hpc Hchk SITE XIRET.
  apply (VBX.vis_leaf_ok L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS (PSIU.Cred I) (PSIU.XIv I) (PSIU.STKF I) PSIU.SCRP PSIU.NF32 (PSIU.U2 I) (PSIU.TP0 I) (PSIU.W_OK I) (PSIU.CRS_OK I) (PSIU.WRS_OK I) (PSIU.IMG_OK I)
    G.CPS G.TAGS G.RETS K (PSIU.DEF0 I) V S2 (PSIU.W_ENC I) Vb ltac:(vm_compute; reflexivity) VADDR S2LT S2ADDR ltac:(vm_compute; reflexivity)
    pc (fun E1 g' M2 => (PMES.enc_inv M2 V S2 g' /\ PML.lits_ok M2 /\ PMES.g_es g' = PMES.estep (PMES.g_es eg) ev /\
                         exists pay, PMES.pay_ok ev pay /\ PMES.g_len g' = PMES.g_len eg + PMES.ev_ind (PMES.g_es eg) ev + pay) /\ Extra E1)
    (fun E1 g' cr' => PMES.ecreditU L cr' g' (KXE E1) (BXE E1)) i c k ps0 j cj ci eg M0c OKV IL Hret Hcj Hpc Hchk).
  - intros E1 R1 M1 model1 E' R' M' cr fx' HAt HAmb HXI Hag HLF CF Ga0 HH HC HFP HK.
    pose proof CF as [HA' _ _ _ _ [Hra Hraok] (Hsp & Hc1 & _) Hstk Htp _ _ _].
    destruct (SITE E1 R1 M1 model1 E' R' M' cr HAt HAmb HXI Hag HLF CF HH HC) as (HArgs & HINV & HGD & HRM & HIMG & HLIT & HCR & HEX).
    pose proof (VS (CH2.den E' (nth i G.BLS []) ++ LBo) cr (sp + CH2.ci_csp ci) (CC.cp_pc cj) V S2 (KXE E1) (BXE E1) eg) as HCPS.
    destruct HA' as (Hmo & _).
    assert (Hmo' : PML.model_ok model1) by (first [exact Hmo | destruct Hmo as (A1 & A2 & A3); exact (conj A1 (conj A2 A3))]).
    apply (HCPS fx' R' M' model1 K HH Hmo' (PSIU.iHKnil I) HFP).
    + cbv beta. split.
      { unfold PML.entry. split; [exact Hra|]. split; [exact Hraok|]. split; [exact Hsp|]. split; [|exact Hstk].
        rewrite Htp. rewrite (PmLayout.ly_tp L LAY). reflexivity. }
      split; [exact Ga0|]. split; [exact HArgs|]. split; [exact HINV|]. split; [exact HGD|]. split; [exact HRM|].
      split; [exact HIMG|]. split; [exact HLIT|]. split; [exact HCR|].
      destruct (PSIU.iOBJS I) as (_ & (V1 & V2 & V3) & (Q1 & Q2 & Q3) & _ & _ & _ & _ & HVS & _ & _).
      unfold PMES.objs_enc, PML.obj_on_stack. repeat split; try assumption; lia.
    + intros fx2 R2 M2 model2 LB' cr' LBk Wc HFP2 HPost HRP HPRES HBV HH2.
      destruct HPost as (g' & pay & HA0 & HINV2 & HES & HPAY & HLEN & HLITS & HLB & HLBk & HWc & HCR2).
      apply (HK fx2 R2 M2 model2 LB' cr' LBk Wc HFP2); [| exact HRP | exact HPRES | exact HBV | exact HH2].
      exists g'. split; [exact HA0|]. split; [split; [split; [exact HINV2|]; split; [exact HLITS|]; split; [exact HES|]; exists pay; split; [exact HPAY | exact HLEN] | exact HEX]|].
      split; [exact HLB|]. split; [exact HLBk|]. split; [exact HWc|]. exact HCR2.
  - intros E1 E' R' M1 M' E2 M2 g' cr' HXI HagE' Hag HLF Hag2 Hnx HPR _ _ ((HINV2 & HLIT2 & HES & HPAY) & HEX) HCR.
    exact (XIRET E1 E' R' M1 M' E2 M2 g' cr' HXI HagE' Hag HLF Hag2 Hnx HPR HINV2 HLIT2 HES HPAY HEX HCR).
Qed.

Lemma bytes_uniq : forall (Mx : mem) p (s1 s2 : list Z), L5.bytes_at RSEGS Mx p s1 -> L5.bytes_at RSEGS Mx p s2 -> length s1 = length s2 ->
  Forall (fun x => 0 <= x <= 255) s1 -> Forall (fun x => 0 <= x <= 255) s2 -> s1 = s2.
Proof.
  intros Mx p s1 s2 H1 H2 HL F1 F2. apply nth_ext with (d := 0) (d' := 0); [exact HL|]. intros n Hn.
  assert (Hn2 : (n < length s2)%nat) by lia.
  pose proof (H1 n Hn) as B1. pose proof (H2 n Hn2) as B2. unfold L5.u8_at in B1, B2. rewrite B1 in B2. injection B2 as B2.
  rewrite Forall_forall in F1, F2. pose proof (F1 _ (nth_In s1 0 Hn)) as R1. pose proof (F2 _ (nth_In s2 0 Hn2)) as R2.
  change (bv_unsigned (Z_to_bv 8 (nth n s1 0)) = bv_unsigned (Z_to_bv 8 (nth n s2 0))) in B2.
  rewrite !Z_to_bv_unsigned in B2. unfold bv_wrap in B2. change (bv_modulus 8) with 256 in B2.
  rewrite !Z.mod_small in B2 by lia. exact B2.
Qed.

Lemma room_lit : forall (ev : PMES.eev) (g' : PMES.eghost) (cc : PMR.ctrl) b r evs al,
  match ev with PMES.EvNull | PMES.EvBool _ => True | _ => False end ->
  PMRF.hreach (PSIU.c0 I) (PSIU.w0 I) cc (b :: r) evs al -> PMR.c_more cc = true -> PMR.dispatch (PMR.c_st cc) (PMR.top cc) b = PMR.ALitDone ->
  Forall PMRA.nots (PMR.c_stack cc) ->
  PSIU.SYNC I g' (evs ++ [PMW.EkLit]) (al + PMR.AL_LIT) -> PMES.g_len g' = PMES.g_len eg + PMES.ev_ind (PMES.g_es eg) ev + PMES.pay_hi ev ->
  PMES.eroomU eg ev.
Proof.
  intros ev g' cc b r evs al Hev (_ & HR) Hmore Hdisp HNS (_ & pay & Hpay & Hlen) Hlen'.
  pose proof (PSIU.iHROOM I) as HRM.
  specialize (HR (S (Z.to_nat (PMRF.phi cc (b :: r)))) ltac:(lia)).
  assert (HB : forall n, PMR.loop (S n) cc (b :: r) =
    PMR.RES (PMR.q_c (PMR.loop n (PMR.set_st (PMR.set_more cc true) (PMR.st_after (PMR.set_more cc true))) r))
            (PMR.q_w (PMR.loop n (PMR.set_st (PMR.set_more cc true) (PMR.st_after (PMR.set_more cc true))) r))
            (PMW.EkLit :: PMR.q_evs (PMR.loop n (PMR.set_st (PMR.set_more cc true) (PMR.st_after (PMR.set_more cc true))) r))
            (PMR.AL_LIT + PMR.q_al (PMR.loop n (PMR.set_st (PMR.set_more cc true) (PMR.st_after (PMR.set_more cc true))) r))
            (PMR.q_code (PMR.loop n (PMR.set_st (PMR.set_more cc true) (PMR.st_after (PMR.set_more cc true))) r))).
  { intros n. cbn [PMR.loop]. rewrite Hmore. unfold PMR.iter. rewrite Hdisp. reflexivity. }
  rewrite HB in HR. unfold PSIU.c0, PSIU.w0 in HR.
  change (PMW.rm_step PMR.the_rm PMW.FParseSome (PSIU.ic0 I) (PMW.inp_win (PSIU.ips I) (PSIU.iwinb I) (PSIU.ix I)))
    with (PMR.r_of (PSIU.iwinb I) (PMR.parse_some (PSIU.ic0 I) (PSIU.iwinb I))) in HRM.
  unfold PMW.wroomrU, PMW.wroomU, PMR.r_of in HRM. cbn [PMW.r_evs PMW.r_allow] in HRM.
  rewrite HR in HRM. unfold PMRF.pre in HRM. cbn [PMR.q_evs PMR.q_al] in HRM.
  assert (IA : forall es l, PMW.ind_run es (evs ++ PMW.EkLit :: l) = PMW.ind_run es (evs ++ [PMW.EkLit]) + PMW.ind_run (PMW.es_run es (evs ++ [PMW.EkLit])) l).
  { intros es l. rewrite <- PMW.ind_run_app, <- app_assoc. reflexivity. }
  rewrite IA in HRM.
  match type of HRM with context [PMW.ind_run (PMW.es_run ?es ?ks) ?l] => pose proof (SPXWU.ind_run_nonneg l (PMW.es_run es ks)) as NN end.
  assert (HS1 : PMRN.SIq (PMR.set_st (PMR.set_more cc true) (PMR.st_after (PMR.set_more cc true)))).
  { apply PMRN.SIq_set_st_plain; [unfold PMR.st_after; destruct (_ =? 0); intros Hx; vm_compute in Hx; discriminate Hx
                                 | unfold PMR.st_after; destruct (_ =? 0); intros Hx; vm_compute in Hx; discriminate Hx | exact HNS]. }
  match type of HRM with context [PMR.q_al (PMR.loop ?n ?c1 ?w)] => pose proof (proj1 (PMRN.loop_alnn n c1 w HS1)) as HAL end.
  unfold PMES.eroomU, PMES.kmax. lia.
Qed.

