Lemma leaf_vis : PMES.visit_null_specU L HI PMES.WD_SCR_X -> PMES.visit_bool_specU L HI PMES.WD_SCR_X ->
  forall i c k ps1 pc j, is_leaf i c k ps1 (CC.TOther pc) -> (pc = 249400 \/ pc = 249664) -> CH2.ret_of G.RETS i k = Some j ->
  CH2V.leaf_okV L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS PMES.eghost VBX.gB (PSIU.Cred I) (PSIU.XIv I) G.CPS K PML.fp_ok eg M0c i c ps1.
Proof.
  intros VNU VBU i c k ps1 pc j IL Hpc Hret.
  pose proof (CH2.leaves_all_sound _ _ _ vis2_ok _ _ _ _ _ IL) as XV.
  pose proof (CH2.leaves_all_sound _ _ _ struct_ok _ _ _ _ _ IL) as XS.
  assert (Hvb : ((pc =? VNULL) || (pc =? VBOOL))%bool = true) by (destruct Hpc as [-> | ->]; reflexivity).
  assert (Hx : is_exit_pc pc = false) by (destruct Hpc as [-> | ->]; reflexivity).
  assert (N1 : (pc =? VECPUSH) = false) by (destruct Hpc as [-> | ->]; reflexivity).
  assert (N2 : (pc =? PUSHB) = false) by (destruct Hpc as [-> | ->]; reflexivity).
  assert (N3 : (pc =? POP) = false) by (destruct Hpc as [-> | ->]; reflexivity).
  assert (N4 : (pc =? PARENT) = false) by (destruct Hpc as [-> | ->]; reflexivity).
  assert (N5 : (pc =? SETEC) = false) by (destruct Hpc as [-> | ->]; reflexivity).
  unfold vis_chk2 in XV. rewrite Hvb, Hret in XV.
  unfold struct_chk in XS. rewrite Hx in XS. unfold call_chk in XS. rewrite Hret in XS.
  destruct (nth_error G.CPS j) as [cj|] eqn:Hcj; [|discriminate XS].
  rewrite N1, N2, N3, N4, N5, Hvb in XS.
  apply andb_prop in XS as [Hpp XS]. apply Z.eqb_eq in Hpp.
  destruct (VBX.vis_chk GT.NF G.HDECL Vb c ps1 cj (nth i G.BLS []) (nth j G.BLS [])) as [ci|] eqn:Hchk; [clear XS | discriminate XS].
  clear Hx N1 N2 N3 N4 N5.
  destruct (kind_of i) eqn:Hki; try discriminate XV.
  destruct (kind_of j) eqn:Hkj; try discriminate XV.
  destruct (rview i c ps1 j (CC.cp_nx (PSM2.cutn j) - APC.NCS)) as [[[[[pv lv] pe] ce] d]|] eqn:Hrv; [|discriminate XV].
  apply andb_prop in XV as [XV H11]. apply andb_prop in XV as [XV Hbl]. apply andb_prop in XV as [XV Hlo].
  apply andb_prop in XV as [XV Hhs]. apply andb_prop in XV as [XV Hlp]. apply andb_prop in XV as [Hss Hi0].
  assert (HA1 : exists za, nth 11 (CA.ps_reglist ps1) (ELit 0) = ELit za /\ (za = 0 \/ za = 1)).
  { destruct (nth 11 (CA.ps_reglist ps1) (ELit 0)); try discriminate H11. eexists. split; [reflexivity|].
    apply orb_prop in H11 as [Q|Q]; apply Z.eqb_eq in Q; [left | right]; exact Q. }
  destruct HA1 as (za & H11e & Hza). clear H11.
  assert (EVS : exists (ev : PMES.eev) (Args : list (Z * Z) -> bvmap 5 word -> mem -> Prop),
    PMES.vtransU L HI PMES.WD_SCR_X pc ev Args /\ match ev with PMES.EvNull | PMES.EvBool _ => True | _ => False end /\
    forall LB E' R' (M' : mem), regs_ok E' (CA.ps_reglist ps1) R' -> Args LB R' M').
  { destruct Hpc as [Hp|Hp].
    - exists PMES.EvNull, (fun _ _ _ => True). split; [rewrite Hp; exact VNU|]. split; [exact Logic.I|]. intros; exact Logic.I.
    - eexists; eexists. split; [rewrite Hp; exact (VBU (za =? 1))|]. split; [exact Logic.I|].
      intros LB E' R' M' HR. cbv beta. hnf. rewrite (HR 11%bv). unfold sr_get. change (bv_eqb (11%bv : bv 5) 0) with false. cbv iota.
      change (ridx 11%bv) with 11%nat. rewrite H11e. cbn [edenot]. destruct Hza as [-> | ->]; reflexivity. }
  destruct EVS as (ev & Args & VS & Hev & HArgs).
  destruct (rview_facts _ _ _ _ _ _ _ _ _ _ Hrv) as (Hld & pvj & Hvwj & Hfl & Hvars).
  pose proof (PSBU.lview_vw _ _ _ _ _ _ _ (ldelta_lview _ _ _ _ _ _ _ _ Hld)) as Hvw.
  apply flds_inj in Hfl. subst pvj.
  destruct (other_facts _ _ _ _ _ IL) as (Hnf & Hbv).
  destruct (PSBU.leaf_nf _ _ _ _ _ IL) as (_ & _ & Hfoot).
  destruct (PSBU.bls2 _ _ _ _ _ _ _ _ IL Hvw) as (sbe & sce & HBL).
  apply CH2.blocks_eqb_eq in Hbl.
  assert (Hcn : CH2.ci_nx ci = (CC.cp_nx cj - APC.NCS)%nat).
  { pose proof Hchk as Hchk'. unfold VBX.vis_chk in Hchk'. destruct (split_lit (nth 10 (CA.ps_reglist ps1) (ELit 0))) as [vb vk].
    lazymatch type of Hchk' with (if ?b then _ else _) = _ => destruct b; [|discriminate] end.
    rewrite (custom_nx _ _ _ _ _ _ _ _ _ _ _ _ _ Hchk'). lia. }
  assert (Hcutj : PSM2.cutn j = cj) by (unfold PSM2.cutn; apply nth_error_nth; exact Hcj).
  rewrite Hcutj in Hvars.
  assert (Hi0' : i <> 0%nat) by (apply negb_true_iff in Hi0; apply Nat.eqb_neq in Hi0; exact Hi0).
  apply Nat.ltb_lt in Hhs.
  destruct (PSM2.rng_of (SR.ps_cells ps1) (PB4.pv_st pv)) as [lo hi] eqn:Hrng. cbv beta iota in Hlo. apply Z.ltb_lt in Hlo.
  destruct (same_state_facts d Hss) as (Dst & Dsst & Dnst & Dmo & Ddn & Dclr).
  assert (KPM : 0 <= hl_k_per_malloc L) by exact (PmLayout.ly_kpm L LAY).
  assert (BOV : 0 <= hl_b_overhead L) by exact (PmLayout.ly_bov L LAY).
  assert (XJ : forall E1 E' R' (M1 M' : mem) E2 (M2 : mem) g',
    PSIU.XI I eg i E1 M1 -> PSIU.SIM I eg i E1 M1 ->
    block_range L (uv E1 (PB4.pv_sb pv)) (uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv)) ->
    (uv E1 pe + uv E1 ce <= uv E1 (PB4.pv_sb pv) \/ uv E1 (PB4.pv_scend pv) <= uv E1 pe) ->
    env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> env_agree (CH2.ci_nx ci) E' E2 ->
    (forall a, (PB2.ls_foot a \/ uv E1 (PB4.pv_sb pv) <= a < uv E1 (PB4.pv_scend pv)) -> M2 (Z_to_bv 64 a) = M' (Z_to_bv 64 a)) ->
    L5.defined M2 (sp - CH.hd_scr G.HDECL) (CH.hd_scr G.HDECL) -> PML.ls_ok g M2 -> WVIS eg g' ->
    PSIU.XI I g' j E2 M2 /\ PSIU.SIM I g' j E2 M2).
  { intros E1 E' R' M1 M' E2 M2 g' HXI HSIM HBRs HDJ HagE' Hag HLF Hag2 HFR HDEF HLS HWV.
    pose proof HXI as HXI0. unfold PSIU.XI in HXI. rewrite Hki, Hvw in HXI.
    destruct HXI as (_ & Hst0 & Hwl & HXD & bm & bd & stack & buf & HCT & _ & HWF & HBB & HWS & _ & _).
    destruct (leaf_view i c k ps1 (CC.TOther pc) pv lv pe ce d E1 E' R' M1 M' bm bd stack buf IL Hld HagE' Hag HLF HCT)
      as (HKN & ULV & USB & USE & USC & UWE & UPE & UCE & (UST & UMO & ULP) & USTL & USSL & UNSL & UMOL & UDNL & USZ & UWP & HADV & UWPL & HUPD).
    rewrite Dst in USTL. rewrite Dsst in USSL. rewrite Dnst in UNSL. rewrite Dmo in UMOL. rewrite Ddn in UDNL. rewrite Dclr in USZ.
    cbn [PSBU.newv] in USSL, UNSL, UMOL, UDNL. cbv beta iota in USTL, USZ.
    rewrite Hcn in Hag2.
    assert (HAG : forall x, In x (pe :: ce :: PSM2.flds lv) -> uv E2 x = uv E' x).
    { intros x Hx. rewrite forallb_forall in Hvars. exact (PB.uv_agree _ E' E2 x Hag2 (Hvars x Hx)). }
    destruct (flds_agree lv pe ce E2 E' HAG) as (FPE & FCE & FLV & FWE & FWP & FST & FSS & FNS & FMO & FDN & FSZ & FSB & FSE & FSC).
    pose proof (PSBU.rng_of_sound E' M' (SR.ps_cells ps1) (PB4.pv_st pv) lo hi (PSBU.leaf_know I c ps1 E' R' M1 M' HLF) Hrng) as HSTR.
    rewrite UST in HSTR.
    pose proof HLF as [_ _ _ HFRM _ _].
    pose proof (PSIU.WIN I) as (W0 & _).
    assert (FRS : forall a, uv E1 (PB4.pv_sb pv) <= a < uv E1 (PB4.pv_scend pv) -> M2 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)).
    { intros a Ha. rewrite (HFR a (or_intror Ha)). pose proof (PSBU.CEIL I) as CL. unfold block_range in HBRs.
      apply (PSBU.frame_low I i c E1 E' M1 M' pe ce [(sbe, sce)] Hfoot HBL HagE' Hag HFRM a); [lia | right; lia]. }
    pose proof HCT as HCT'. unfold PSIU.contents in HCT'.
    destruct HCT' as (CBY & CSE & CLN & CWE & CWP & CSZ & CBL & CNB & CMO & CDN & CKY).
    assert (XIj : PSIU.XI I g' j E2 M2).
    { unfold PSIU.XI. rewrite Hkj, Hvwj.
      split; [exact HDEF|]. split; [intros _; exact (Hst0 Hi0')|].
      split; [intros Hl; apply Hwl; rewrite Hl in Hlp; exact Hlp|].
      split.
      { unfold PSIU.XDEP. rewrite Hkj, Hvwj. unfold PSIU.XDEP in HXD. rewrite Hki, Hvw in HXD. cbv beta iota in HXD |- *.
        destruct HWV as (ev0 & pay0 & Hev0 & Hes0 & _ & _). rewrite Hes0, (depth_scalar _ _ Hev0), HXD, FLV, ULV. reflexivity. }
      exists bm, bd, stack, buf. rewrite (ps_of_agree lv pe ce E2 E' bm bd stack buf HAG), (HUPD bm bd buf), USTL, USSL, UNSL.
      split.
      { unfold PSIU.contents. rewrite FSB, FSE, FSC, FWE, FWP, FSZ, FCE, FST, FMO, FDN, FLV, USB, USE, USC, UWE, UWP, UCE, USTL, UMOL, UDNL, USZ, ULV.
        split; [apply (PSBU.bytes_frame M1 M2 _ stack); [intros a Ha; apply FRS; lia | exact CBY]|].
        split; [exact CSE|]. split; [exact CLN|]. split; [reflexivity|]. split; [lia|]. split; [exact CSZ|]. split; [exact CBL|].
        split; [intros Hn; exfalso; unfold PML.ST_NUMBER in Hn; lia|]. split; [exact CMO|]. split; [exact CDN|]. exact CKY. }
      split; [exact HLS|].
      split; [exact (PSBU.wf_same (PSIU.ps_of pv pe ce E1 bm bd stack buf) bd (uv E1 ce) (uv E1 pe) _ HWF)|].
      split.
      { unfold PML.buf_bound in HBB |- *. destruct HBB as (HB1 & HB2). split; [|exact HB2].
        unfold PML.buf_need, PSIU.ps_of in HB1 |- *. cbn [PSS.upd PML.ps_buf PML.ps_more PML.ps_st PML.ps_sst] in HB1 |- *.
        rewrite PSBU.winlen_of in HB1 by lia. unfold PSS.upd. rewrite PSBU.winlen_of by lia. lia. }
      split; [exact HWS|].
      split; [intros HJ; exfalso; unfold I_HLO, I_HHI, I_HN, I_L, I_HS in *; lia|].
      intros HJ; exfalso; unfold I_L0, I_HS in *; lia. }
    split; [exact XIj|].
    exact (OBL_VIS_RET i c k ps1 pc j cj pv lv pe ce d E1 E' R' M1 M' E2 M2 g' IL Hpc Hpp Hret Hcj Hld Hki Hkj HagE' Hag HLF Hag2 HXI0 HSIM HWV HFR FRS XIj). }
  apply (vis_leaf_okE pc ev Args
    (fun E1 => CH2.den E1 (nth i G.BLS []) = [(uv E1 pe, uv E1 ce); (uv E1 (PB4.pv_sb pv), uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv))] /\
               uv E1 ce <= 2 ^ 27 /\ block_range L (uv E1 pe) (uv E1 ce) /\
               block_range L (uv E1 (PB4.pv_sb pv)) (uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv)) /\
               (uv E1 pe + uv E1 ce <= uv E1 (PB4.pv_sb pv) \/ uv E1 (PB4.pv_scend pv) <= uv E1 pe))
    (fun E1 => PSIU.ikx I + PML.kleft (PSIU.ps_of pv pe ce E1 false false [] []) * hl_k_per_malloc L)
    (fun E1 => PSIU.ibxu I + PMX.pbytes L (PSIU.ps_of pv pe ce E1 false false [] [])) i c k ps1 j cj ci VS IL Hret Hcj Hpp Hchk).
  - intros E1 R1 M1 model1 E' R' M' cr HAt HAmb HXIv Hag HLF CF HH HC. cbv beta.
    pose proof CF as [_ HR Hreq _ _ _ _ _ _ HagE' _ _]. rewrite Hreq in HR.
    destruct HXIv as (HXI & HXV & HSIM).
    pose proof (HAMBc i E1 M1 model1 HAmb) as HA.
    pose proof HXI as HXI0. unfold PSIU.XI in HXI. rewrite Hki, Hvw in HXI.
    destruct HXI as (HDEF1 & _ & _ & _ & bm & bd & stack & buf & HCT & HLS1 & HWF & _ & _ & _ & _).
    destruct (PSBU.leaf_state I eg M0c OKV i c k ps1 (CC.TOther pc) pv lv pe ce d E1 R1 E' R' M1 M' model1 bm bd stack buf IL Hld HAt HA Hag HLF HCT)
      as (_ & _ & _ & _ & USB & USE & _ & _ & _ & _ & (UST & UMO & _) & _ & _ & _ & UMOL & _ & _ & _ & _ & _ & HBY' & _ & HLSF & _ & HDEN & _).
    rewrite Dmo in UMOL. cbn [PSBU.newv] in UMOL.
    pose proof HDEN as HDEN0.
    rewrite HBL, !PB.den_cons in HDEN. change (CH2.den E1 []) with (@nil (Z * Z)) in HDEN.
    assert (Hsbc : uv E1 sbe = uv E1 (PB4.pv_sb pv) /\ uv E1 sce = uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv)) by (injection HDEN; intros; split; assumption).
    destruct Hsbc as (Hsb & Hsc).
    destruct (PSBU.own_blocks I eg M0c i E1 M1 model1 pe ce sbe sce HA HBL) as (HBRb & HBRs0 & _ & _ & HDJ0 & _).
    rewrite Hsb, Hsc in HBRs0, HDJ0.
    pose proof HWF as (_ & _ & _ & Hscap & _).
    pose proof HC as HC'. apply (proj1 (PSIU.cred_of_blocks I eg i E1 cr (PSIU.ps_of pv pe ce E1 bm bd stack buf) HDEN0 Hscap)) in HC'.
    pose proof HC' as (_ & _ & Hbc & _).
    assert (Hs1056 : PML.ps_scap (PSIU.ps_of pv pe ce E1 bm bd stack buf) <= 1056) by (destruct Hscap as [Hq|[Hq|[Hq|[Hq|[Hq|[]]]]]]; rewrite <- Hq; lia).
    pose proof (PSBU.xinv_leaf I eg M0c i c k ps1 (CC.TOther pc) E1 E' R' M1 M' M1 model1 IL HA HagE' Hag HLF HXV) as (HINV' & HLIT').
    pose proof (PSBU.ls_frame M1 M' g HLSF (PSIU.iHG I) HLS1) as HLSM.
    pose proof HLF as [_ _ _ _ _ HGR].
    assert (HDEF' : L5.defined M' (sp - CH.hd_scr G.HDECL) (CH.hd_scr G.HDECL)) by exact (PSBU.grows_def M1 M' _ _ HGR HDEF1).
    pose proof (PSBU.rng_of_sound E' M' (SR.ps_cells ps1) (PB4.pv_st pv) lo hi (PSBU.leaf_know I c ps1 E' R' M1 M' HLF) Hrng) as HSTR.
    rewrite UST in HSTR.
    assert (HRM : PMES.eroomU eg ev).
    { set (gf := PMES.EG (PMES.estep (PMES.g_es eg) ev) (PMES.g_len eg + PMES.ev_ind (PMES.g_es eg) ev + PMES.pay_hi ev) (PMES.g_rep eg) (PMES.g_sb eg) (PMES.g_scap eg)).
      assert (HWV : WVIS eg gf).
      { exists ev, (PMES.pay_hi ev). split; [exact Hev|]. split; [reflexivity|]. split; [|reflexivity].
        clear -Hev. destruct ev; cbn; try contradiction; reflexivity. }
      destruct (XJ E1 E' R' M1 M' E' M' gf HXI0 HSIM HBRs0 ltac:(lia) HagE' Hag HLF (CC.env_agree_refl _ _) (fun a _ => eq_refl) HDEF' HLSM HWV) as (_ & HSj).
      unfold PSIU.SIM in HSj. rewrite Hkj, Hvwj in HSj.
      destruct HSj as (cc & b0 & r0 & evs & al & HRch & _ & Hmore & Hdisp & HMV & HSY).
      destruct HMV as (bm2 & bd2 & stack2 & buf2 & HCT2 & HRG2 & _ & (Hcore & _)).
      destruct Hcore as (_ & Hcm & _ & _ & Hcs).
      apply (room_lit ev gf cc b0 r0 evs al Hev HRch Hmore Hdisp); [| exact HSY | reflexivity].
      rewrite Hmore in Hcm. cbn [PSIU.ps_of PML.ps_more] in Hcm.
      pose proof HCT2 as HCT2'. unfold PSIU.contents in HCT2'. destruct HCT2' as (C2BY & C2SE & _ & _ & _ & _ & _ & _ & C2MO & _).
      pose proof HCT as HCT'. unfold PSIU.contents in HCT'. destruct HCT' as (_ & CSE & _ & _ & _ & _ & _ & _ & CMO & _).
      assert (Hbm : bm = true).
      { apply PSBU.b2z_inj1. rewrite <- CMO, <- UMOL, C2MO, <- Hcm. reflexivity. }
      assert (FN : Forall (fun x => 0 <= x <= 255 /\ PMRA.nots x) stack).
      { destruct HWF as (_ & _ & _ & _ & C0 & T0 & Hstk & HCo & HT).
        cbn [PSIU.ps_of PML.ps_stack PML.ps_more PML.ps_st] in Hstk, HT. specialize (HT Hbm).
        destruct HT as (_ & _ & _ & Htr & _ & _).
        rewrite Hstk. constructor; [unfold PMRA.nots, PML.ST_ROOT, PML.ST_STRING, PML.ST_NUMBER; lia|].
        apply Forall_app. split.
        - eapply Forall_impl; [|exact HCo]. intros x [Hx|Hx]; rewrite Hx; unfold PMRA.nots, PML.ST_OBJECT, PML.ST_ARRAY, PML.ST_STRING, PML.ST_NUMBER; lia.
        - unfold PML.transient, PML.is_expect in Htr.
          destruct Htr as [(-> & _)|[(-> & Hs)|[(S0 & HS & -> & _)|(S0 & HS & -> & _)]]].
          + constructor.
          + exfalso. unfold PML.ST_STRING in Hs. lia.
          + cbn [In] in HS. constructor; [|constructor]. unfold PMRA.nots, PML.ST_STRING, PML.ST_NUMBER. lia.
          + cbn [In] in HS. constructor; [|constructor; [|constructor]]; unfold PMRA.nots, PML.ST_SLASH_STAR, PML.ST_STRING, PML.ST_NUMBER; lia. }
      assert (Hl2 : length stack2 = length stack) by lia.
      assert (Hst2 : stack2 = stack).
      { apply (bytes_uniq M' (uv E1 (PB4.pv_sb pv))); [rewrite <- USB; exact C2BY | exact HBY' | exact Hl2 | exact HRG2 |].
        eapply Forall_impl; [|exact FN]. intros x [Hx _]. exact Hx. }
      rewrite Hcs. cbn [PSIU.ps_of PML.ps_stack]. rewrite Hst2. eapply Forall_impl; [|exact FN]. intros x [_ Hx]. exact Hx. }
    split; [exact (HArgs _ E' R' M' HR)|]. split; [exact HINV'|]. split; [clear -Hev; destruct ev; cbn; tauto|]. split; [exact HRM|].
    split; [exact (proj1 HLSM)|]. split; [exact HLIT'|].
    split; [exact (SPXWU.ecredit_of_pxU L KPM BOV cr (PSIU.ps_of pv pe ce E1 bm bd stack buf) eg (PSIU.ikx I) (PSIU.ibxu I) HC' (PSIU.iHkx I) (PSIU.iHbxu0 I) Hs1056)|].
    split; [exact HDEN0|]. split; [exact Hbc|]. split; [exact HBRb|]. split; [exact HBRs0|]. lia.
  - intros E1 E' R' M1 M' E2 M2 g' cr' HXIv HagE' Hag HLF Hag2 Hnx HPR HINV2 HLIT2 HES HPAY HBK HCR. cbv beta in HBK, HCR.
    destruct HXIv as (HXI & HXV & HSIM).
    destruct HBK as (HD1 & Hce & HBRb & HBRs & HDJ).
    pose proof HBRs as HBRs0.
    pose proof HXI as HXI0. unfold PSIU.XI in HXI. rewrite Hki, Hvw in HXI.
    destruct HXI as (HDEF1 & _ & _ & _ & bm & bd & stack & buf & HCT & HLS1 & HWF & _ & _ & _ & _).
    pose proof HLF as [_ _ _ HFRM _ HGR].
    pose proof (PSBU.CEIL I) as CL. pose proof (PSIU.OBJR I) as (O1 & O2 & O3 & O4 & O5 & O6 & O7). pose proof (PSIU.OBJRX I) as (X1 & X2 & X3 & X4 & _).
    pose proof (PSIU.SPF I) as (_ & _ & S3 & S4).
    pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI. pose proof (PmLayout.ly_errno L LAY) as LER.
    assert (HDE' : CH2.den E' (nth i G.BLS []) = CH2.den E1 (nth i G.BLS [])) by exact (CH2.den_agree _ E1 E' _ Hag Hbv).
    pose proof HPR as HPR0. destruct HPR as (HK2 & _ & _).
    unfold block_range in HBRb, HBRs. rewrite ILO, IHI in HBRb, HBRs.
    assert (KS : forall a, hl_img_lo L <= a < hl_img_hi L -> ~ hl_alloc_static L a -> ~ in_errno L a -> (a < PML.LIT_LO \/ PML.LIT_HI <= a) ->
                  M2 (Z_to_bv 64 a) = M' (Z_to_bv 64 a)).
    { intros a Hi Hs He Hl. apply HK2. rewrite ILO, IHI in Hi. split; [lia|]. split; [right; right; split; [rewrite ILO, IHI; lia | exact Hs]|].
      split; [exact He|]. intros w Hw. unfold PMES.W_enc in Hw. destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; unfold L5.in_rng; cbn [fst snd];
      unfold PMES.O_STACK, PMES.O_DEPTH, PML.LIT_LO, PML.LIT_HI in *; lia. }
    assert (FRSB : forall a, uv E1 (PB4.pv_sb pv) <= a < uv E1 (PB4.pv_scend pv) -> M2 (Z_to_bv 64 a) = M' (Z_to_bv 64 a)).
    { intros a Ha. apply HK2. split; [lia|]. split.
      { left. exists (uv E1 (PB4.pv_sb pv), uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv)). split; [|cbn [fst snd]; lia].
        apply in_or_app. left. rewrite HDE', HD1. right. left. reflexivity. }
      split; [unfold in_errno; rewrite LER; lia|].
      intros w Hw. unfold PMES.W_enc in Hw. destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; unfold L5.in_rng; cbn [fst snd];
      unfold PMES.O_STACK, PMES.O_DEPTH, PML.LIT_LO, PML.LIT_HI; lia. }
    assert (FRLS : forall a, PB2.ls_foot a -> M2 (Z_to_bv 64 a) = M' (Z_to_bv 64 a)).
    { intros a Ha. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. apply KS; [rewrite ILO, IHI; lia | intros X; pose proof (PmLayout.ly_static L LAY a X); lia
                                                                | unfold in_errno; rewrite LER; lia | unfold PML.LIT_LO, PML.LIT_HI; lia]. }
    assert (HLSM' : PML.ls_ok g M').
    { apply (PSBU.ls_frame M1 M' g); [|exact (PSIU.iHG I) | exact HLS1].
      intros a Ha. apply (PSBU.frame_low I i c E1 E' M1 M' pe ce [(sbe, sce)] Hfoot HBL HagE' Hag HFRM a); [lia | right; lia]. }
    assert (HLSM2 : PML.ls_ok g M2).
    { eapply PB2.ls_ok_keep; [exact FRLS | exact (PSIU.iHG I) | exact HLSM']. }
    assert (HDEF2 : L5.defined M2 (sp - CH.hd_scr G.HDECL) (CH.hd_scr G.HDECL)).
    { apply (hpres_def _ _ _ _ M' M2 _ _ HPR0); [exact (PSBU.grows_def M1 M' _ _ HGR HDEF1) | rewrite PSIU.SCRV in *; lia | rewrite PSIU.SCRV; lia]. }
    assert (HWV : WVIS eg g') by (destruct HPAY as (pay & Hp1 & Hp2); exists ev, pay; split; [exact Hev|]; split; [exact HES|]; split; [exact Hp1 | exact Hp2]).
    destruct (XJ E1 E' R' M1 M' E2 M2 g' HXI0 HSIM HBRs0 ltac:(lia) HagE' Hag HLF Hag2
                 ltac:(intros a [Ha|Ha]; [exact (FRLS a Ha) | exact (FRSB a Ha)]) HDEF2 HLSM2 HWV) as (XIj & SIMj).
    split; [split; [exact XIj|]; split; [exact (conj HINV2 HLIT2) | exact SIMj]|].
    pose proof HWF as (_ & _ & _ & Hscap & _).
    assert (Hd2 : CH2.den E2 (nth j G.BLS []) = PML.ps_blocks (PSIU.ps_of pv pe ce E1 false false [] [])).
    { rewrite Hbl. rewrite (CH2.den_agree (CC.cp_nx c) E' E2 _ (CC.env_agree_le _ _ _ _ Hag2 Hnx) Hbv), HDE', HD1. reflexivity. }
    apply (proj2 (PSIU.cred_of_blocks I g' j E2 cr' _ Hd2 Hscap)).
    pose proof (PSIU.KXBX I g') as (K1 & K2). unfold PSIU.kxe in K1.
    unfold PML.pcredit_x, PML.pcredit, PSIU.kxe. unfold PMES.ecreditU, PMX.pbytes in HCR. cbn [fst snd].
    rewrite PMX.kenc_eq in *.
    split; [lia|]. split; [lia|]. split; [exact Hce|]. split; lia.
(* [comment removed for export] *)
Qed.
